import * as M from './model.js';
import {knownIds} from './community-life.js';
import * as A from './academic-year.js';
import * as P from './planner.js';
import * as C from './curriculum.js';
import * as W from './staff-work.js';
import * as Support from './student-support.js';
export const DESTINATIONS=[{id:'park',name:'지역 생태공원',distance:1,fee:0,room:'playground',subjects:'생태 관찰·지도 읽기'},{id:'museum',name:'고장 생활사 전시관',distance:12,fee:4000,room:'museum',subjects:'생활 자료·우리 고장 조사'},{id:'science-center',name:'어린이 과학문화관',distance:22,fee:6000,room:'museum',subjects:'질문 만들기·과학 탐구'},{id:'library-center',name:'지역 어린이도서관',distance:2,fee:0,room:'library',subjects:'자료 찾기·작가 되어 보기'},{id:'local',name:'학교 주변 마을 배움길',distance:.5,fee:0,room:'playground',subjects:'관찰·인터뷰 질문·안전한 이동'}];
export const COMPETITIONS=[['science','과학 탐구 발표','과학','관찰 기록과 근거를 설명하는 발표'],['invention','생활 속 발명 제안','실과','실제 불편·조건·시안을 비교하는 제안'],['debate','자료 기반 토론','국어','주장·근거·반론을 구분한 토론'],['reading','독서 표현 나눔','국어','읽은 근거를 담은 글·그림·낭독'],['art','미술 작품 전시','미술','표현 의도·재료 선택과 수정 과정'],['music','작은 음악 발표','음악','함께 맞춘 리듬·소리·연습 과정'],['sports','협동 체육 도전','체육','역할과 거리 조절·모두의 참여'],['coding','디지털 문제 해결','실과','문제를 나누고 시험·수정한 결과'],['speech','이야기 발표','국어','듣는 사람을 고려한 구성과 표현'],['environment','환경 실천 프로젝트','창체','관찰·작은 실천·변화 확인']];
export function data(s){return s.operations??={schema:1,trips:{},competitions:[],schoolElections:[],council:[],market:null,maintenance:[],observations:[],orders:[],lessonTags:{},nextTag:null};}
export function occupied(s,room,day,period){if(room==='classroom')return null;const b=s.academic.reservations.find(r=>r.room===room&&r.day===day&&r.period===period&&!r.cancelled);if(b)return b.owner==='class'?null:'다른 학급 예약';if(M.REGIONS[s.config.region].classes>1&&(day*13+period*7+room.length+s.config.seed)%7===0)return '다른 학급 정기 사용';return null;}
export function reserve(s,room,day,period,subject){if(!M.ROOMS[room]||!Number.isInteger(day)||day<s.day||day>s.academic.end||!A.schoolDay(s,day)||!Number.isInteger(period)||period<1||period>6||!C.subjectRooms(subject).includes(room))return {error:'해당 과목에 맞는 장소·앞으로의 등교일·교시를 선택해 주세요.'};const slot=M.todaySchedule({...s,day,academic:{...s.academic,phase:'term'}}).find(r=>r.period===period);if(!slot||slot.subject!==subject||slot.event)return {error:'학급 시간표의 해당 과목 수업을 확인해 주세요.'};if(day===s.day&&s.minute>=slot.end)return {error:'지나간 교시는 예약할 수 없습니다.'};const conflict=occupied(s,room,day,period);if(conflict)return {error:conflict+'과 겹칩니다. 다른 날짜나 교실 대안을 선택해 주세요.'};if(s.academic.reservations.some(r=>r.day===day&&r.period===period&&!r.cancelled))return {error:'이 교시에 학급이 사용할 장소를 이미 예약했습니다.'};s.academic.reservations.push({id:'room-'+s.academic.year+'-'+s.academic.reservations.length,room,day,period,subject,owner:'class',cancelled:false,date:M.stamp(s)});return {ok:true};}
export function cancelReservation(s,id){const r=s.academic.reservations.find(x=>x.id===id);if(!r||r.day<s.day||r.cancelled)return false;r.cancelled=true;return true;}
export function changeLesson(s,day,period,subject,reason){if(!A.schoolDay(s,day)||day<s.day||!Number.isInteger(period)||period<1||period>6||![...M.subjects(s.config.grade),'창체'].includes(subject)||String(reason).trim().length<5)return {error:'앞으로의 등교일·교시·유효 과목과 변경 사유를 확인해 주세요.'};const rows=structuredClone(A.plannedSchedule(s,day)),slot=rows.find(r=>r.period===period),start=[540,590,640,690,790,840][period-1];if(day===s.day&&s.minute>=start||A.eventsOn(s,day).some(e=>e.start<=start&&start<e.end&&!['openclass','peer'].includes(e.kind)))return {error:'시작한 수업과 학교 행사 시간은 임의 변경할 수 없습니다.'};if(rows.some(r=>r.specialist&&r.period===period))return {error:'전담 수업 변경은 전담교사 협의에서 별도로 처리해 주세요.'};if(slot)slot.subject=subject;else rows.push({subject,period,start,end:start+40,specialist:false});rows.sort((a,b)=>a.period-b.period);s.academic.overrides[day]=rows;data(s).observations.push({type:'schedule-change',day,period,subject,reason:String(reason).slice(0,300),date:M.stamp(s)});for(const r of s.academic.reservations)if(r.day===day&&r.period===period&&r.subject!==subject)r.cancelled=true;return {ok:true};}
export function specialistChange(s,day,period,mode){const rows=structuredClone(A.plannedSchedule(s,day)),slot=rows.find(r=>r.period===period);if(!slot?.specialist||day<s.day||day===s.day&&s.minute>=slot.start||!['cover','move'].includes(mode))return {error:'앞으로의 전담 수업과 협의 방법을 선택해 주세요.'};slot.specialist=false;slot.specialistChange=mode==='cover'?'담임 대체 협의':'전담 결강 후 보완 협의';s.academic.overrides[day]=rows;data(s).observations.push({type:'specialist-change',day,period,subject:slot.subject,mode,date:M.stamp(s),evaluationOwner:mode==='cover'?'담임 관찰 후 전담 인계':'전담교사와 평가 보완'});return {ok:true};}
export function planTrip(s,id,destination,transport){const e=s.academic.events.find(e=>e.id===id);const place=DESTINATIONS.find(x=>x.id===destination);if(!e||e.kind!=='trip'||!place||!['walk','schoolbus','coach','alternative'].includes(transport))return false;if(e.day<=s.day)return {error:'체험학습 전에 장소와 이동수단을 협의해 주세요.'};if(transport==='walk'&&place.distance>2)return {error:'이 장소는 도보 범위를 벗어납니다. 차량 또는 가까운 장소를 선택해 주세요.'};if(s.config.region==='island'&&place.distance>2)return {error:'섬 밖 왕복은 당일 시간 안에 어렵습니다. 섬 안 배움길이나 지역 협력 장소를 선택해 주세요.'};const key=e.id,old=data(s).trips[key];if(old?.status==='reserved')return {error:'예약된 계획을 취소한 뒤 변경해 주세요.'};const cost=transport==='alternative'?0:s.students.length*place.fee+(transport==='coach'?180000:0),grant=s.students.length*20000;if(cost>grant)return {error:'별도 체험학습 지원 예산을 초과합니다. 비용이 낮은 대안을 선택해 주세요.'};const waiting=transport==='schoolbus'&&(s.config.seed+e.day)%3!==0;const plan={destination,transport,status:waiting?'waiting':'reserved',cost,grant,balance:grant-cost,requested:M.stamp(s),requestedDay:s.day,decisionDay:s.day+2,notice:false,settled:false};if(waiting)plan.balance=grant;data(s).trips[key]=plan;if(transport==='alternative'){e.room='classroom';e.title='교내 대체 체험활동';}else e.room=place.room;return {ok:true,waiting};}
export function tripAction(s,id,action){const p=data(s).trips[id];if(!p)return false;if(action==='check'&&p.status==='waiting'){if(s.day<p.decisionDay)return {error:'차량 담당자의 회신 예정일에 다시 확인해 주세요.'};p.status=(s.config.seed+s.day)%2?'unavailable':'reserved';if(p.status==='reserved')p.balance=p.grant-p.cost;return {ok:true};}if(action==='cancel'&&!p.settled){p.status='cancelled';p.balance=p.grant;return {ok:true};}if(action==='settle'){const e=s.academic.events.find(x=>x.id===id);if(e?.status!=='completed'||p.status!=='reserved'||p.settled)return {error:'실제 체험활동 후 한 번 정산할 수 있습니다.'};p.settled=true;p.settledAt=M.stamp(s);return {ok:true};}return false;}
export function competition(s,id,ids){const c=COMPETITIONS.find(x=>x[0]===id);const members=[...new Set(ids)].filter(id=>s.students.some(x=>x.id===id));if(!c||!members.length)return {error:'활동을 희망한 학생을 한 명 이상 선택해 주세요.'};if(data(s).competitions.some(x=>x.kind===id&&x.term===A.term(s)))return {error:'이번 학기에 같은 프로젝트를 이미 계획했습니다.'};data(s).competitions.push({id:'contest-'+s.academic.year+'-'+data(s).competitions.length,kind:id,term:A.term(s),members,step:0,records:[],result:null});return {ok:true};}
export function contestStep(s,id,text){const p=data(s).competitions.find(x=>x.id===id);if(!p||p.step>=3)return false;if(String(text).trim().length<8||!W.free(s,20))return {error:'학생이 준비한 근거·발표·돌아보기를 적고 20분을 확보해 주세요.'};const present=p.members.filter(id=>M.isPresent(s,id)&&Support.available(s,id));if(!present.length)return {error:'참여 학생이 없어 활동을 진행할 수 없습니다.'};M.advance(s,20);p.records.push({step:p.step,text:String(text).slice(0,1000),present,date:M.stamp(s)});p.step++;if(p.step===3){p.result='탐구·표현 과정 공유 완료';for(const id of present)M.remember(s,s.students.find(x=>x.id===id),'희망한 프로젝트에서 준비와 표현 과정을 나누었다.',1);}return {ok:true};}
export function schoolElection(s,action){const d=data(s),term=A.term(s);let e=d.schoolElections.find(e=>e.term===term);if(!e){e={term,stage:0,candidates:[{name:'김하늘',promise:'쉬는 시간 놀이 의견 모으기'},{name:'박가온',promise:'도서관 안내 더 쉽게 만들기'},{name:'이마루',promise:'학교 공간의 작은 불편 찾기'}],history:[],result:null};d.schoolElections.push(e);}if(e.stage>=3)return {error:'이번 학기 전교 선거 결과가 확정되었습니다.'};if(!W.free(s,10)&&!['창체','국어'].includes(M.currentSlot(s).subject))return {error:'10분의 아침·쉬는 시간 또는 관련 교과 시간을 확보해 주세요.'};if(M.currentSlot(s).end-s.minute<10)return {error:'다음 수업을 넘기지 않는 10분이 필요합니다.'};M.advance(s,10);e.history.push({stage:e.stage,action,date:M.stamp(s)});e.stage++;if(e.stage===3){const candidates=e.candidates.map((c,i)=>({...c,votes:20+(s.config.seed+i*13)%27}));const max=Math.max(...candidates.map(c=>c.votes));e.result={candidates,winners:candidates.filter(c=>c.votes===max).map(c=>c.name),rule:'가상 학교의 전교 선거관리 결과 · 동점은 공동대표'};M.addMessage(s,'all','학생회 담당교사','전교 선거 결과를 공유합니다. 학급 의견은 학생회 제안함으로 계속 받습니다.',{senderId:'colleague',plannerScanned:true});}return {ok:true};}
export function council(s,text){if(String(text).trim().length<8||!W.free(s,10))return {error:'학급에서 모은 의견을 적고 10분을 확보해 주세요.'};M.advance(s,10);data(s).council.push({id:'council-'+data(s).council.length,text:String(text).slice(0,1000),day:s.day,status:'협의 요청',followup:null,date:M.stamp(s)});return {ok:true};}
export function councilFollowup(s,id,text){const p=data(s).council.find(x=>x.id===id);if(!p||p.status==='점검 완료'||String(text).trim().length<8||!W.free(s,10))return {error:'학생이 직접 실천한 내용과 확인 결과를 적어 주세요.'};M.advance(s,10);p.status='점검 완료';p.followup=String(text).slice(0,1000);p.completed=M.stamp(s);return {ok:true};}
export function market(s,mode){const d=data(s);if(d.market)return {error:'장터 준비 기록이 이미 있습니다.'};if(!['exchange','donation','sale'].includes(mode))return false;d.market={mode,initialStock:s.students.length*2,stock:s.students.length*2,exchanged:0,donated:0,sold:0,receipts:0,donationAmount:0,roles:s.students.map((st,i)=>({id:st.id,role:['안내','물품 점검','가격표·교환권','정리'][i%4]})),ledger:[],settled:false};return {ok:true};}
export function marketTrade(s,count){const p=data(s).market,e=s.academic.events.find(x=>x.kind==='market');count=Number(count);if(!p||p.settled||e?.day!==s.day||e?.status!=='running'||!Number.isInteger(count)||count<1||count>p.stock)return {error:'장터 운영 중 남은 공동 물품 수량 안에서 기록해 주세요.'};p.stock-=count;if(p.mode==='exchange')p.exchanged+=count;else if(p.mode==='sale'){p.sold+=count;p.receipts+=count*1000;}else p.donated+=count;p.ledger.push({count,mode:p.mode,date:M.stamp(s)});return {ok:true};}
export function settleMarket(s){const p=data(s).market,e=s.academic.events.find(x=>x.kind==='market');if(!p||p.settled||e?.status!=='completed')return {error:'장터 활동이 끝난 뒤 수량을 확인해 정산해 주세요.'};if(p.stock+p.exchanged+p.donated+(p.sold||0)!==(p.initialStock??s.students.length*2))return {error:'남은 물품과 교환·기부 수량이 맞지 않습니다.'};p.settled=true;p.donationAmount=p.receipts||0;p.settledAt=M.stamp(s);return {ok:true};}
export function maintenance(s,room,item,detail){const d=data(s);if(!M.ROOMS[room]||String(detail).trim().length<8||!String(item).trim())return {error:'고장 장소·물품·관찰한 상태를 적어 주세요.'};if(d.maintenance.some(r=>r.room===room&&r.item===item&&r.status!=='closed'))return {error:'같은 물품의 수리 요청을 이미 접수했습니다.'};d.maintenance.push({id:'repair-'+d.maintenance.length,room,item:String(item).slice(0,60),detail:String(detail).slice(0,500),status:'requested',day:s.day,readyDay:s.day+(s.config.region==='island'?3:1),history:[{status:'사용 중지·행정실 접수',date:M.stamp(s)}]});return {ok:true};}
export function repairStep(s,id){const r=data(s).maintenance.find(x=>x.id===id);if(!r||r.status==='closed')return false;if(r.status==='requested'){r.status='scheduled';r.history.push({status:'행정실 부품·방문 예약',date:M.stamp(s)});}else if(r.status==='scheduled'){if(s.day<r.readyDay)return {error:'행정실의 부품·방문 예정일에 확인해 주세요.'};r.status='repaired';r.history.push({status:'행정실 수리 완료',date:M.stamp(s)});}else {r.status='closed';r.history.push({status:'담임 사용 확인',date:M.stamp(s)});}return {ok:true};}
export function valid(s){const d=s.operations;if(d==null)return true;return d.schema===1&&d.trips&&Object.values(d.trips).every(p=>['waiting','reserved','unavailable','cancelled'].includes(p.status)&&p.balance>=0&&p.cost>=0&&p.balance<=p.grant)&&Array.isArray(d.competitions)&&d.competitions.every(c=>COMPETITIONS.some(x=>x[0]===c.kind)&&c.step>=0&&c.step<=3&&c.members.every(id=>knownIds(s).has(id)))&&Array.isArray(d.schoolElections)&&d.schoolElections.every(e=>[1,2].includes(e.term)&&e.stage>=0&&e.stage<=3)&&Array.isArray(d.council)&&Array.isArray(d.maintenance)&&Array.isArray(d.observations)&&(!d.market||d.market.stock+d.market.exchanged+d.market.donated+(d.market.sold||0)===(d.market.initialStock??s.students.length*2));}
